{
  "items": [
    {
      "name": "Finset.le_sum_schlomilch",
      "module_name": "Mathlib.Analysis.PSeries",
      "kind": "theorem",
      "type": "∀ {M : Type u_1} [inst : AddCommMonoid M] [inst_1 : PartialOrder M] [IsOrderedAddMonoid M] {f : ℕ → M} {u : ℕ → ℕ},\n  (∀ ⦃m n : ℕ⦄, 0 < m → m ≤ n → f n ≤ f m) →\n    (∀ (n : ℕ), 0 < u n) →\n      Monotone u →\n        ∀ (n : ℕ),\n          ∑ k ∈ Finset.range (u n), f k ≤\n            ∑ k ∈ Finset.range (u 0), f k + ∑ k ∈ Finset.range n, (u (k + 1) - u k) • f (u k)"
    },
    {
      "name": "Finset.le_sum_schlomilch'",
      "module_name": "Mathlib.Analysis.PSeries",
      "kind": "theorem",
      "type": "∀ {M : Type u_1} [inst : AddCommMonoid M] [inst_1 : PartialOrder M] [IsOrderedAddMonoid M] {f : ℕ → M} {u : ℕ → ℕ},\n  (∀ ⦃m n : ℕ⦄, 0 < m → m ≤ n → f n ≤ f m) →\n    (∀ (n : ℕ), 0 < u n) →\n      Monotone u → ∀ (n : ℕ), ∑ k ∈ Finset.Ico (u 0) (u n), f k ≤ ∑ k ∈ Finset.range n, (u (k + 1) - u k) • f (u k)"
    },
    {
      "name": "AntitoneOn.sum_le_integral",
      "module_name": "Mathlib.Analysis.SumIntegralComparisons",
      "kind": "theorem",
      "type": "∀ {x₀ : ℝ} {a : ℕ} {f : ℝ → ℝ},\n  AntitoneOn f (Set.Icc x₀ (x₀ + ↑a)) → ∑ i ∈ Finset.range a, f (x₀ + ↑(i + 1)) ≤ ∫ (x : ℝ) in x₀..x₀ + ↑a, f x"
    },
    {
      "name": "Finset.sum_schlomilch_le'",
      "module_name": "Mathlib.Analysis.PSeries",
      "kind": "theorem",
      "type": "∀ {M : Type u_1} [inst : AddCommMonoid M] [inst_1 : PartialOrder M] [IsOrderedAddMonoid M] {f : ℕ → M} {u : ℕ → ℕ},\n  (∀ ⦃m n : ℕ⦄, 1 < m → m ≤ n → f n ≤ f m) →\n    (∀ (n : ℕ), 0 < u n) →\n      Monotone u →\n        ∀ (n : ℕ), ∑ k ∈ Finset.range n, (u (k + 1) - u k) • f (u (k + 1)) ≤ ∑ k ∈ Finset.Ico (u 0 + 1) (u n + 1), f k"
    },
    {
      "name": "Finset.sum_schlomilch_le",
      "module_name": "Mathlib.Analysis.PSeries",
      "kind": "theorem",
      "type": "∀ {M : Type u_1} [inst : AddCommMonoid M] [inst_1 : PartialOrder M] [IsOrderedAddMonoid M] {f : ℕ → M} {u : ℕ → ℕ}\n  {C : ℕ},\n  (∀ ⦃m n : ℕ⦄, 1 < m → m ≤ n → f n ≤ f m) →\n    (∀ (n : ℕ), 0 < u n) →\n      (∀ (n : ℕ), 0 ≤ f n) →\n        Monotone u →\n          SuccDiffBounded C u →\n            ∀ (n : ℕ),\n              ∑ k ∈ Finset.range (n + 1), (u (k + 1) - u k) • f (u k) ≤\n                (u 1 - u 0) • f (u 0) + C • ∑ k ∈ Finset.Ico (u 0 + 1) (u n + 1), f k"
    },
    {
      "name": "ENNReal.le_tsum_schlomilch",
      "module_name": "Mathlib.Analysis.PSeries",
      "kind": "theorem",
      "type": "∀ {u : ℕ → ℕ} {f : ℕ → ENNReal},\n  (∀ ⦃m n : ℕ⦄, 0 < m → m ≤ n → f n ≤ f m) →\n    (∀ (n : ℕ), 0 < u n) →\n      StrictMono u → ∑' (k : ℕ), f k ≤ ∑ k ∈ Finset.range (u 0), f k + ∑' (k : ℕ), (↑(u (k + 1)) - ↑(u k)) * f (u k)"
    }
  ]
}
